class TokenEndpointTest extends OidcIntegrationTestCase
{
    private TokenController $controller;

    protected function setUp(): void
    {
        parent::setUp();
        $this->controller = $this->container->get(TokenController::class);
    }

    public function testClientCredentialsReturnsAccessToken(): void
    {
        $request = $this->makeRequest('POST', '/oauth/openid/tenant1/token', [
            'grant_type' => 'client_credentials',
            'client_id' => self::CLIENT_ID,
            'client_secret' => self::CLIENT_SECRET,
            'scope' => 'openid api:read',
        ]);

        $response = $this->controller->post($request, new Response(200), ['tenant' => self::TENANT]);

        $this->assertSame(200, $response->getStatusCode());
        $body = $this->decodeJson($response);
        $this->assertSame('Bearer', $body['token_type']);
        $this->assertArrayHasKey('access_token', $body);
        $this->assertArrayHasKey('expires_in', $body);
        $this->assertArrayNotHasKey('id_token', $body);
        $this->assertArrayNotHasKey('refresh_token', $body);
    }

    public function testClientCredentialsAccessTokenContainsExpectedClaims(): void
    {
        $request = $this->makeRequest('POST', '/oauth/openid/tenant1/token', [
            'grant_type' => 'client_credentials',
            'client_id' => self::CLIENT_ID,
            'client_secret' => self::CLIENT_SECRET,
            'scope' => 'api:read',
        ]);

        $response = $this->controller->post($request, new Response(200), ['tenant' => self::TENANT]);

        $this->assertSame(200, $response->getStatusCode());
        $body = $this->decodeJson($response);
        $token = $body['access_token'];

        $signer = $this->container->get(\Civi\Lughauth\Features\OAuth\TokenSecurity\Domain\Gateway\TokenSigner::class);
        $payload = $signer->verifyTokenPayload(self::TENANT, $token);

        $this->assertNotNull($payload);
        $this->assertSame(self::CLIENT_ID, $payload['azp']);
        $this->assertSame(self::CLIENT_ID, $payload['sub']);
        $this->assertSame(self::TENANT, $payload['tenant']);
        $this->assertStringContainsString('api:read', $payload['scope']);
        $this->assertSame('client_credentials', $payload['token_use']);
    }

